 if item is null then raise exception 'unknown synthetic fixture tag %',tag; end if;
 -- Refresh only BEFORE display. Expiry is not in He; Hq binds the fresh exact P.
 deadline := (clock_timestamp()+interval '1 hour')::text;
 p := jsonb_set(item->'payload','{expires_at}',to_jsonb(deadline));
 p := jsonb_set(p,'{approved_snapshot,original,expires_at}',to_jsonb(deadline));
 item := jsonb_set(item,'{payload}',p);
 return jsonb_set(item,'{hash}',to_jsonb(encode(sha256(convert_to(public.career_apply_canonical(p),'UTF8')),'hex')));
end $fn$;
create function pg_temp.cc_full_payload(tag text) returns jsonb language sql as $$ select pg_temp.cc_full_item(tag)->'payload' $$;
